const msg = ($input.first().json.message) || {};
const raw = String(msg.text || '').trim();
let text = raw;
if (text.charAt(0) === '/') text = text.slice(1);
const parts = text.split(/\s+/);
let first = String(parts[0] || '').toLowerCase();
first = first.split('@')[0];
const rest = parts.slice(1).join(' ');
const noArg = { out:'out', o:'out', now:'now', n:'now', sum:'sum', s:'sum', week:'week', w:'week', tags:'tags', t:'tags' };
const oneArg = { in:'in', i:'in', switch:'switch', sw:'switch', add:'add', '+':'add', del:'del', '-':'del' };
let command = 'unknown';
let arg = '';
let arg2 = '';
if (noArg[first]) {
  command = noArg[first];
} else if (oneArg[first]) {
  command = oneArg[first];
  arg = String(parts[1] || '').toLowerCase();
} else if (first === 'rename') {
  command = 'rename';
  arg = String(parts[1] || '').toLowerCase();
  arg2 = String(parts[2] || '').toLowerCase();
} else if (first === 'note') {
  command = 'note';
  arg = rest;
} else if (raw !== '' && parts.length === 1) {
  command = 'bare_tag';
  arg = first;
} else {
  command = 'unknown';
}
const chatId = (msg.chat || {}).id;
return [{ json: { command, arg, arg2, raw, chatId } }];

